import { S3Client, PutObjectCommand } from '@aws-sdk/client-s3';

const b2 = new S3Client({
  region: '{{b2_region}}',
  endpoint: `https://s3.{{b2_region}}.backblazeb2.com`,
  credentials: {
    accessKeyId: '{{key_id}}',
    secretAccessKey: '{{application_key}}',
  },
});

export async function b2Upload(key: string, body: Buffer | Uint8Array, contentType: string) {
  await b2.send(new PutObjectCommand({
    Bucket: '{{bucket_name}}',
    Key: key,
    Body: body,
    ContentType: contentType,
  }));
  return { bucket: '{{bucket_name}}', key };
}
